WITH payload AS (SELECT $archive_payload$[{"id":"fe15ead1-1cb9-5bdc-a07c-926b8b85f6f7","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترير دعوى -دعوى خاصة ( حق خاص) ،قضية مشتركة ،امتناع املدعي من حترير الدعوى وطلب االكتفاء بالئحة اعتراضية من حكم سابق ،من شروط صحة سماع الدعوى أن تكون محررة ،رد دعوى ( صرف نظر ).","document_number":"33312576","case_number":"32605456","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/23","year":"1434","subject":"حترير دعوى -دعوى خاصة ( حق خاص) ،قضية مشتركة ،امتناع املدعي من حترير الدعوى وطلب االكتفاء بالئحة اعتراضية من حكم سابق ،من شروط صحة سماع الدعوى أن تكون محررة ،رد دعوى ( صرف نظر ).","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33312576:‬تاريخه‪1433/6/23 :‬هـ‬\n                        ‫رقم الدعوى‪32605456:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3441082‬تاريخه‪1434/2/19 :‬هـ‬\n\n\n     ‫حترير دعوى ‪ -‬دعوى خاصة ( حق خاص) ‪ ،‬قضية مشتركة ‪ ،‬امتناع‬\n     ‫املدعــي مــن حتريــر الدعــوى وطلــب االكتفــاء بالئحــة اعتراضيــة مــن‬\n     ‫حكــم ســابق ‪ ،‬مــن شــروط صحــة ســماع الدعــوى أن تكــون محــررة ‪ ،‬رد‬\n                                                     ‫دعــوى ( صــرف نظــر )‪.‬‬\n\n\n\n                        ‫‪ -‬املادة الثالثة والستون من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n     ‫ورد للمحكمــة حكــم منقــوض مــن محكمــة االســتئناف ‪ -‬بإحالتهــا‬\n     ‫للجنــة أخــرى للنظــر فيهــا ‪ -‬حضــر وكيــل املدعــي وطلــب منــه حتريــر‬\n     ‫دعــواه فأبــرز مذكــرة جــرى االطــاع عليهــا فظهــر بــأن مضمونهــا‬\n     ‫االعتــراض علــى احلكــم الســابق صــدق جــزء منــه واجلــزء اآلخــر نقــض‬\n     ‫ولــم تتضمــن حتريــرا لدعــواه ‪ -‬طلــب منــه أن يحــرر دعــواه فأجــاب بأنــه‬\n     ‫ليــس لديــه ســوى مــا قدمــه يف هــذه املذكــرة ‪ -‬عليــه وبنــاء علــى املــادة‬\n     ‫الثالثــة والســتني مــن نظــام املرافعــات الشــرعية والئحتهــا التنفيذيــة ‪،‬‬\n     ‫وألن املدعــي لــم يحــرر دعــواه ‪ ،‬وإلقــراره بأنــه ليــس لديــه ســوى مــا‬\n     ‫قدمــه ‪ ،‬لــذا فقــد قــررت اللجنــة القضائيــة املشــكلة باألكثريــة صــرف‬\n     ‫النظــر عــن دعــوى املدعــي وكالــة حتــى يحررهــا‪ -‬بعــرض احلكــم علــى‬\n\n‫‪11‬‬\n\f‫وكيــل املدعــي قــرر عــدم القناعــة فجــرى تســليمه صــورة مــن صــك‬\n‫احلكــم وأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1433/06/23‬هـ‬\n‫لدينا نحن ‪ ...........‬و‪ ...........‬و‪ ...........‬القضاة باحملكمة العامة مبحافظة‬\n‫ـاء علــى املعاملــة املقيــدة بهــذه احملكمــة برقــم ‪321628471‬‬    ‫اخلــرج وبنـ ً‬\n‫وتاريــخ ‪1432/12/25‬ه ـ واحملالــة مــن فضيلــة رئيــس احملكمــة‬\n‫املســاعد برقــم ‪ 32605456‬وتاريــخ ‪1432/12/25‬ه ـ املنقوضــة مبوجــب‬\n‫القــرار الصــادر مــن الدائــرة اخلماســية مبحكمــة االســتئناف بالريــاض‬\n‫برقــم ‪ 32297402‬وتاريــخ ‪1432/11/6‬ه ـ افتتحــت اجللســة الســاعة ‪55‬‬\n‫‪ 12 :‬وفيهــا حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫ا عــن ‪ ................‬ســعودي اجلنســية مبوجــب‬\n                                                ‫رقــم ‪ ...........‬بصفتــه وكي ـ ً‬\n‫الســجل املدنــي رقــم‪ ...........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل بالدلــم برقــم ‪...........‬وتاريــخ ‪1432/12/17‬ه ـ املجلــد‪...........‬‬\n‫املخــول لــه فيهــا حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة وحضــور‬\n‫اجللســات وســماع الدعــوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح‬\n‫وطلــب اليمــن وردهــا وقبــول احلكــم ونفيــه واالســتالم والتســليم‬\n‫وحضــر حلضــوره املدعىعليــه ‪...........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن ‪ ...........‬ســعودي اجلنســية‬  ‫املدنــي رقــم‪ ...........‬بصفتــه وكي ـ ً‬\n‫مبوجــب الســجل املدنــي رقــم ‪...........‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة عــدل الدملبرقــم ‪...........‬وتاريــخ ‪1433/3/8‬ه ـ املجلــد‪...........‬‬\n‫املخــول لــه فيهــا حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة واإلقــرار‬\n\n                                                                                      ‫‪12‬‬\n\f     ‫واإلنــكار واالســتالم والتســليم ويف هــذه اجللســة جــرى ســؤال املدعــي‬\n     ‫باحلــق اخلــاص وكالــة عــن دعــواه فأحــال إلــى مذكرتيــه التــي ســبق وأن‬\n     ‫قيــدت لدينــا األولــى برقم ‪ 33902180‬وتاريــخ ‪1433/5/12‬هـ ومكونة‬                 ‫ّ‬\n     ‫مــن ســبع ورقــات والثانيــة برقــم ‪ 331181997‬وتاريــخ ‪1433/6/23‬ه ـ‬\n     ‫ومكونــة مــن ثــاث ورقــات وباإلطــاع عليهمــا تبــن أن املذكرتــن‬\n     ‫الســابقتني لــم تتضمــن حتريــر ًا لدعــواه وإمنــا هــي عبــارة عــن اعتــراض‬\n     ‫علــى احلكــم الســابق الصــادر مــن هــذه احملكمــة برقــم ‪/2/10‬ض‬\n     ‫وتاريــخ ‪1431/4/18‬ه ــواملكتسب للقطعيــة يف جــزء منــه مبوجــب‬\n     ‫قــرار مصادقــة ونقــض محكمــة االســتئناف رقــم ‪32297402‬وتاريــخ‬\n     ‫‪1432/11/6‬ه ـ وبإفهــام املدعــي وكالــة بذلــك وأن عليــه تقــدمي دعــوى‬\n     ‫محــررة يف احلــق اخلــاص ضــد ‪ - ...........‬إن رغــب موكلــه ذلــك ‪ -‬فقــال‬\n     ‫قدمــت يف املذكرتــن الســابقتني‪ ،‬فبنــاء علــى مــا‬    ‫ليــس لــدي ســوى مــا ّ‬\n     ‫تقــدم وبنــاء علــى املــادة الثالثــة والســتني والئحتيهــا التنفيذيتــن مــن نظام‬\n     ‫املرافعــات الشــرعية ولكــون املدعــي وكالــة باحلــق اخلــاص لــم يحــرر‬\n     ‫دعــواه ومبــا أن املدعــي وكالــة قــد ذكــر بأنــه ليــس لديــه ســوىما قـ ّـدم‬\n     ‫يف أوراق املذكرتــن املشــار إليهــا أعــاه لــكل مــا تقــدم فقــد حكمنــا‬\n     ‫نحــن القاضيــان ‪ ...........‬و‪ ...........‬بصــرف النظــر عــن دعــوى املدعــي‬\n     ‫وكالــة حتــى يحررهــا وبعــرض احلكــم علــى املدعــي وكالــة لــم يقنــع به‬\n     ‫فجــرى تســليمه نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن‬\n     ‫يومـ ًا يســقط بعدهــا حقــه يف االســتئناف ففهــم ذلــك ختمــت يف الســاعة‬\n     ‫الواحــدة وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد حــرر‬\n     ‫يف ‪1433/6/23‬ه ـ األول ‪...........‬يف احلــق اخلــاص وإفهــام املدعــي اخلــاص‬\n     ‫بــأن لــه احلــق يف إقامــة دعــواه ضــده عنــد رغبتــه تنظــر الدعــوى مــن جديد‬\n\n\n‫‪13‬‬\n\f‫حســب املتبــع واهلل املوفــق وبعــد اإلطــاع علــى املذكرتــن املكونــة مــن‬\n‫عشــر ورقــات ‪ -‬املشــار إليهــا آنفـ ًا ‪ -‬ووجودهــا يتضمــن االعتــراض علــى‬\n‫احلكــم الســابق وطلــب إعــادة األوراق إلــى التحقيــق يــرى فضيلته صرف‬\n            ‫النظــر عــن دعــوى املدعــي وكالــة لعــدم االختصــاص ‪ .‬أ‪ .‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n‫القضايــا اخلماســية مبحكمــة االســتئناف بالرياض علــى املعاملة الواردة‬\n‫مــن فضيلــة رئيــس محكمةاخلــرج العامــة املكلــف برقــم‪33/902180‬‬\n‫وتاريــخ ‪1433/12/21‬ه ـ املرفــق بهــا القــرار الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمةالشــيخ‪........... /‬والشــيخ‪........... /‬والشــيخ‪/‬‬\n‫‪...........‬برقــم ‪1 33312576‬وتاريــخ ‪1433/6/23‬ه ـ اخلــاص بدعــوى‪/‬‬\n‫‪......................‬وبالوكالــة عــن ‪...........‬ضــد‪ ........... /‬وقــد تضمــن القــرار‬\n‫حكــم أصحــاب الفضيلــة علــى النحــو املفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة نقــرر املصادقــة علــى حكــم األكثريــة‬\n‫بصــرف النظــر عــن دعــوى املدعــي وكالــة حتــى يحررهــا مــع تنبيــه‬\n‫صاحبــي الفضيلــة مســتقبال إلــى أنــه يكتفــى بتحريــر وجهــة النظــر‬\n          ‫واإلجابــة عليهــا يف الضبــط دون القــرار الشــرعي واهلل املوفــق‬\n\n\n\n\n                                                                                            ‫‪14‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":11,"source_page_end":14,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b241b1ac8a14ccbfcf75bd85897c26145825397fd16b2f0575556856aa16af0f","normalized_text_hash":"17aebdb6729d18573bd63d86450b2cb7a06ca4bade5b068104dc4e282a677bb2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p11-33312576"},{"id":"4ee339ce-740e-59ef-a7b6-d785e387ad08","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى غير محررة -بيع -إفراغ عقار -من شرط قبول الدعوى أن تكون محررة -صرف النظر عن دعوى ألنها غير محررة -إفهام املدعي بأن له احلق يف تقدمي الدعوى بعد حتريرها .1قوله صلى اهلل عليه وسلم (( إمنا أقضي على نحو ما أسمع)) .2من شروط الدعوى أن تكون محررة معلومة املدعى به دعوى املدعي ضد املدعى عليه وكالة أنه اشترى من شخصني قد توفيا عقار ا من مخطط ميلكانه وأنه ال يعرف اسم املخطط وال","document_number":"33476217","case_number":"33251142","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"دعوى غير محررة -بيع -إفراغ عقار -من شرط قبول الدعوى أن تكون محررة -صرف النظر عن دعوى ألنها غير محررة -إفهام املدعي بأن له احلق يف تقدمي الدعوى بعد حتريرها .1قوله صلى اهلل عليه وسلم (( إمنا أقضي على نحو ما أسمع)) .2من شروط الدعوى أن تكون محررة معلومة املدعى به دعوى املدعي ضد املدعى عليه وكالة أنه اشترى من شخصني قد توفيا عقار ا من مخطط ميلكانه وأنه ال يعرف اسم املخطط وال","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/12/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33476217 :‬‬\n                         ‫َر ْق ُم الدعوى‪33251142 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 33476217‬تاريخه‪1433/12/22 :‬هـ‬\n\n\n      ‫دعــوى غيــر محــررة ‪ -‬بيــع ‪ -‬إفــراغ عقــار ‪ -‬مــن شــرط قبــول الدعــوى أن‬\n      ‫تكــون محــررة ‪ -‬صــرف النظــر عــن دعــوى ألنهــا غيــر محــررة ‪ -‬إفهــام‬\n                      ‫املدعــي بــأن لــه احلــق يف تقــدمي الدعــوى بعــد حتريرهــا‬\n\n\n\n\n            ‫‪ .1‬قوله صلى اهلل عليه وسلم (( إمنا أقضي على نحو ما أسمع))‬\n                  ‫‪ .2‬من شروط الدعوى أن تكون محررة معلومة املدعى به‬\n\n\n\n\n      ‫دعــوى املدعــي ضــد املدعــى عليــه وكالــة أنــه اشــترى مــن شــخصني‬\n      ‫قــد توفيــا عقــار ًا مــن مخطــط ميلكانــه وأنــه ال يعــرف اســم املخطــط وال‬\n      ‫رقــم القطعــة املباعــة وال طولهــا وذلــك مببلــغ قــدره اثنــان وأربعــون ألف ـ ًا‬\n      ‫وســتمائة وســبعون ريــا ًال وانــه ســدد مــن القيمــة عشــرة آالف وســتمائة‬\n      ‫وســبعون ريــا ًال وأن البائعــن ماتــا ولــم يفرغــا العقــار وطلــب إلــزام املدعى‬\n      ‫عليهــم أصالــة بإفــراغ العقــار ‪ -‬طلــب القاضــي مــن املدعــي بيــان األرض‬\n      ‫املشــتراة فذكــر أنــه ال يعرفهــا وال يســتطيع حتديدهــا ‪ -‬أجــاب املدعــى‬\n      ‫عليــه وكالــة أن الدعــوى غيــر واضحــة ‪ -‬قــرر ناظــر القضيــة أن الدعوى‬\n      ‫غيــر محــررة ومــن شــروط ســماع الدعــوى أن تكــون محــررة لــذا فقــد‬\n      ‫صــرف النظــر عــن الدعــوى وافهــم املدعــي بــان لــه حــق إقامــة الدعــوى‬\n\n‫‪15‬‬\n\f‫بعــد حتريرهــا ‪ -‬قــرر املدعــي عــدم القناعــة ‪ -‬صــدر قــرار محكمــة‬\n                ‫االســتئناف مبكــة املكرمــة باملوافقــة علــى احلكــم‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة العامة مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا من فضيلة رئيــس احملكمة العامة‬\n‫مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33251142‬وتاريــخ ‪1433/04/11‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 33673433‬وتاريــخ ‪ 1433/04/11‬ه ـ‬\n‫ففــي يــوم األربعــاء املوافــق‪ 1433/12/22‬ه ـ حضــر ‪ ............‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ ............‬وحضــر حلضــوره ‪.........‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ..........‬الوكيــل عــن‬\n‫‪ ..........‬و أصالــة عــن نفســهم وبصفتهــم مــن ورثــة والدهــم مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة رقــم ‪........‬يف‬\n‫‪1432/11/5‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة واقامة وســماع‬\n‫الدعــاوى وادعــى األول قائــا‪ :‬ان ‪...‬و‪ ...‬ميلــكان مخطط ال اعرف اســمه‬\n‫وقــد اشــتريت منهــم قطعــة ســكنية مســاحتها ‪426,79‬م‪ 2‬مببلــغ قــدره‬\n‫اثنــان واربعــون الــف وســتمائة وتســعة وســبعون ريــال وقــد ســددت يف‬\n‫مكتــب ‪ ...‬للعقــار مبلغــا قــدره عشــرة االف وســت مئــة وســبعون الــف‬\n‫ريــال وقــد مــات املدعــى عليهمــا ولــم يفرغــا لــي العقــار اطلــب الــزام‬\n‫املدعــى عليهمــا بافــراغ العقــار لــي هكــذا ادعــى وبســؤاله عــن اســم‬\n‫املخطــط ورقمــه وحــدود واطــوال القطعــة التــي اشــتراها أجــاب قائــا‬\n‫ال أعلمهــا وال ميكــن ان احضرهــا يف جلســات قادمــة هكــذا أجــاب‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه اجــاب قائــا ان دعــوى املدعــي‬\n\n                                                                                    ‫‪16‬‬\n\f     ‫غيــر واضحــة هكــذا أجــاب فبنــاء علــى مــا ســلف وألن دعــوى املدعــي‬\n     ‫غيــر محــررة وملــا هــو متقــرر ان مــن شــروط الدعــوى ان تكــون محــررة‬\n     ‫معلومــة املدعــى بــه ولقــول النبــي صلــى اهلل عليــه وســلم ( امنــا اقضــي على‬\n     ‫نحــو مــا اســمع ) لذلــك كلــه فقــد صرفــت النظــر عــن دعــوى املدعــي‬\n     ‫واخليــت ســبيل املدعــى عليــه منهــا وبذلــك حكمــت وافهمــت املدعــي‬\n     ‫بــان لــه احلــق يف تقــدمي دعــوى بعــد حتريرهــا حتريــرا واضحــا وباعــان‬\n     ‫احلكــم عليهمــا قــرر املدعــى عليــه قناعتــه باحلكــم امــا املدعــي فقــرر‬\n     ‫املعارضــة بــدون الئحــة وأمــرت ببعــث كامــل اوراق املعاملــة حملكمــة‬\n     ‫االســتئناف لتدقيقــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/12/22‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n     ‫أنــا القاضــي باحملكمــة العامــة مبحافظــة جــدة وقــد عــادت املعاملــة‬\n     ‫مــن محكمــة االســتئناف مبكــة املكرمــة بخطــاب فضيلــة رئيســها‬\n     ‫رقــم ‪ 332277526‬وتاريــخ ‪1434/01/12‬ه ـ واملرفــق بــه قــرار الدائــرة‬\n     ‫احلقوقيــة الرابعــة رقــم ‪ 33476217‬وتاريــخ ‪1433/12/22‬ه ـ ونــص‬\n     ‫احلاجــة منــه ( وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n     ‫احلكــم ) وللبيــان جــرى إثباتــه وإحلاقــه علــى ســجله وبــاهلل التوفيــق‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                ‫‪1434/02/02‬ه ـ ‪.‬‬\n     ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n     ‫منــا االطــاع نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف‬\n     ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر‬\n     ‫مــن فضيلــة الشــيخ ‪ ..........‬القاضــي باحملكمــة العامــة بجــدة واملســجل‬\n\n\n‫‪17‬‬\n\f‫بعــدد ‪ 33476217‬وتاريــخ ‪1433/12/22‬ه ـ املتضمــن دعــوى ‪..........‬‬\n‫ضــد ‪ ( ..........‬وكالــة ) واحملكــوم فيــه مبــادون باطنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم وصلــى اهلل علــى نبينــا‬\n                                       ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪18‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":15,"source_page_end":18,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"92622016181d273c774771f16d3c47c8de765e539fb6ab6b9c3936de5231272f","normalized_text_hash":"a0e7660f584451cc60a9d63ac803d2928f572cc72fc480ab984671fa4a8ff689","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p15-33476217"},{"id":"a5e2443a-bf8c-5b63-9dda-703d6b7ad744","document_type":"judgment","category":"judicial","subcategory":"general","title":"عدم حترير الدعوى -قسمة تركة -مطالبة املدعي بنصيبه من اإلرث -وجوب حترير الدعوى قبل استجواب املدعى عليه -صرف النظر عن الدعوى حتى حتريرها .","document_number":"34385856","case_number":"34540354","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة الرس","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/24","year":"1434","subject":"عدم حترير الدعوى -قسمة تركة -مطالبة املدعي بنصيبه من اإلرث -وجوب حترير الدعوى قبل استجواب املدعى عليه -صرف النظر عن الدعوى حتى حتريرها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34385856 :‬تاريخه‪1434/12/24 :‬هـ‬                             ‫بكمبنلكم‬\n                         ‫رقم الدعوى‪34540354 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 35105241‬تاريخه‪1435/1/4 :‬هـ‬\n\n\n      ‫عــدم حتريــر الدعــوى ‪ -‬قســمة تركــة‪ -‬مطالبــة املدعــي بنصيبــه مــن‬\n      ‫اإلرث‪ -‬وجــوب حتريــر الدعــوى قبــل اســتجواب املدعــى عليــه‪ -‬صــرف‬\n                                       ‫النظــر عــن الدعــوى حتــى حتريرهــا ‪.‬‬\n\n\n\n\n           ‫‪ -‬املادة (‪ 63‬و ‪ )1‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه بــأن املدعــى عليــه أخوه قام باالســتيالء‬\n      ‫علــى نصيــب والدتــه مــن إرث والــده وأخيــه مــن أرض وأغنــام وغيــر ذلــك‬\n      ‫ويقــدر جميعــه بأربعمائــة ألــف ريــال يطلــب نصيبــه مــن إرث والدتــه‬\n      ‫وأخيــه هكــذا ادعــى ‪ -‬جــرى إفهــام املدعــي بتحريــر دعــواه ببيــان‬\n      ‫نصيبــه مــن اإلرث املدعــى بــه وأســماء املورثــن وإثبــات وفاتهمــا وبيــان‬\n      ‫ورثتهمــا اســتناد ًا للمــادة ‪ 63‬مــن نظــام املرافعــات الشــرعية ‪ -‬رفــض‬\n      ‫املدعــي حتريــر دعــواه ‪ -‬ومبــا أن املدعــي امتنــع عــن حتريــر دعــواه وبنــاء‬\n      ‫علــى املــادة ‪ 1/ 63‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة‬\n      ‫ونصهــا ( إذا امتنــع املدعــي عــن حتريــر دعــواه أو عجــز عنــه فعلــى‬\n      ‫القاضــي أن يحكــم بصــرف النظــر عــن الدعــوى حتــى حتريرهــا‪- )..‬‬\n      ‫احلكــم بصــرف النظــر عــن الدعــوى حتــى حتريرهــا ‪ -‬قنــع املدعــى عليــه‬\n\n‫‪19‬‬\n\f‫باحلكــم واعتــرض املدعــي بــدون الئحــة ‪ -‬صــدق احلكــم مــن دائــرة‬\n         ‫األحــوال الشــخصية مبحكمــة االســتئناف مبنطقــة القصيــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة الــرس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة الــرس برقــم ‪ 34540354‬وتاريــخ‬\n‫‪1434/12/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342742112‬وتاريــخ‬\n‫‪1434/12/02‬ه ـ ففــي يــوم اإلثنــن املوافق‪1434/12/23‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر ‪.....‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪.....‬وادعــى علــى احلاضــر معــه ‪.....‬ســعودي بالســجل املدنــي رقــم ‪.....‬‬\n‫قائــا يف دعــواه ( أن املدعــى عليــه هــو أخــي وقــد قــام باالســتيالء علــى‬\n‫نصيــب والدتــي مــن إرث والــدي وأخــي رحمهمــا اهلل مــن أرض وأغنــام‬\n‫وغيــر ذلــك ويقــدر جميعــه بأربعمائــة ألــف ريــال أطلــب نصيبــي مــن‬\n‫إرث والدتــي وأخــي حيــث رفــض إعطائــي أي شــيء ويدعــي أن الوالــدة‬\n‫رحمهــا اهلل أعطتــه نصيبهــا مــن اإلرث لــذا أطلــب نصيبــي مــن إرث‬\n‫والدتــي وأخــي واملقــدر بأربعمائــة ألــف ريــال ) هكــذا أدعــى باللفــظ‬\n‫الــذي نطــق بــه املدعــي وبعــد ســماع الدعــوى وقبــل ســؤال املدعــى عليــه‬\n‫عــن الدعــوى ومبــا أن الدعــوى غيــر محــررة وبنــاء علــى املــادة رقــم ‪63‬‬\n‫مــن نظــام املرافعــات الشــرعية ونصهــا ( علــى القاضــي أن يســأل املدعــي‬\n‫عمــا هــو الزم لتحريــر دعــواه قبــل اســتجواب املدعــى عليــه وليــس لــه‬\n‫ردهــا لتحريرهــا وال الســير فيهــا قبــل ذلــك ) أ‪.‬ه ـ لــذا فقــد طلبــت مــن‬\n‫املدعــي حتريــر دعــواه وذلــك ببيــان نصيبــه مــن اإلرث املدعــى به وأســماء‬\n\n                                                                                     ‫‪20‬‬\n\f     ‫املورثــن واثبــات وفاتهمــا وبيــان ورثتهمــا فأجــاب املدعــي بقولــه دعــواي‬\n     ‫محــررة وال حتتــاج حتريــر أكثــر ممــا ذكــر وجميــع األوراق عنــد‬\n     ‫املدعــى عليــه هكــذا أجــاب ومبــا أن املدعــي امتنــع عــن حتريــر دعــواه‬\n     ‫وبنــاء علــى املــادة رقــم ‪ 1/63‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n     ‫التنفيذيــة ونصهــا ( إذا امتنــع املدعــي عــن حتريــر دعــواه أو عجــز عنــه‬\n     ‫فعلــى القاضــي أن يحكــم بصــرف النظــر عــن الدعــوى حتــى حتريرهــا‬\n     ‫ويعامــل مــن لــم يقنــع بتعليمــات التمييــز ) أ‪.‬ه ـ لــذا فقــد حكمــت‬\n     ‫بصــرف النظــر عــن الدعــوى حتــى حتريرهــا وبعــد النطــق باحلكــم‬\n     ‫وتالوتــه عليهمــا أفهمتهمــا بطــرق االعتــراض املقــررة ومواعيدهــا فقــرر‬\n     ‫املدعــى عليــه قناعتــه وقــرر املدعــي عــدم قناعتــه وطلــب رفعــه حملكمــة‬\n     ‫االســتئناف بــدون مذكــرة اعتراضيــة واختتمــت اجللســة الســاعة ‪: 20‬‬\n     ‫‪ 09‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم ‪ .‬حــرر يف ‪1434/12/23‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n     ‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n     ‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامة بـمحافظة الرس برقم (‪ )342742112‬وتاريخ ‪1434/12/29‬هـ؛‬\n     ‫املقيــدة لــدى احملكمــة برقــم (‪ )342742112‬وتاريــخ ‪1435/1/2‬هــ؛‬\n     ‫اخلاصــة ب ــدعوى‪..... /‬ضــد‪ ..... /‬بشــأن مطالبتــه بنصيبــه مــن إرثــه مــن‬\n     ‫والدتــه؛ املنتهيــة بالصــك الصــادر مــن فضيلــة الشــيخ‪ ..... /‬القاضــي‬\n     ‫باحملكمــة؛ املســجل برقــم (‪ )34385856‬وتاريــخ ‪1434/12/24‬هــ؛‬\n     ‫املتضمــن حكــم فضيلتــه بصــرف النظــر عــن الدعــوى؛ علــى النحــو‬\n     ‫املفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n\n\n‫‪21‬‬\n\f‫املصادقــة علــى ماحكــم بــه فضيلتــه‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                        ‫نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪22‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":19,"source_page_end":22,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d032a0c27910f77aa1de90bc83960ff9104863476ebcf78e435c7dda988d37ba","normalized_text_hash":"0241bda66f4318e1790f4999001f6856ae51772671a21d3ede3773d8dd2c8ef7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p19-34385856"},{"id":"65d5ee0c-bef0-553e-9a31-97c390f94c17","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترير دعوى -مطالبة برفع مساحي ألرض -وجوب حترير الدعوى قبل استجواب املدعى عليه -االمتناع عن حترير الدعوى يؤدي إلى احلكم بصرف النظر عنها -احلكم بصرف النظر ال يكفي إلثبات التملك وال يقوم مقام حجة االستحكام وال يستند عليه","document_number":"34358756","case_number":"34476708","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة الرس","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/12","year":"1434","subject":"حترير دعوى -مطالبة برفع مساحي ألرض -وجوب حترير الدعوى قبل استجواب املدعى عليه -االمتناع عن حترير الدعوى يؤدي إلى احلكم بصرف النظر عنها -احلكم بصرف النظر ال يكفي إلثبات التملك وال يقوم مقام حجة االستحكام وال يستند عليه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/11/12 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34358756 :‬‬\n                         ‫َر ْق ُم الدعوى‪34476708 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34374956‬تاريخه‪1434/12/1 :‬هـ‬\n\n\n      ‫حتريــر دعــوى ‪ -‬مطالبــة برفــع مســاحي ألرض ‪ -‬وجــوب حترير الدعوى‬\n      ‫قبــل اســتجواب املدعــى عليــه ‪ -‬االمتنــاع عــن حتريــر الدعــوى يــؤدي‬\n      ‫إلــى احلكــم بصــرف النظــر عنهــا ‪ -‬احلكــم بصــرف النظــر ال يكفــي‬\n      ‫إلثبــات التملــك وال يقــوم مقــام حجــة االســتحكام وال يســتند عليــه‬\n                                                                  ‫يف أي إفــراغ‪.‬‬\n\n\n\n\n               ‫‪ -‬املادة ‪ 1/ 63‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه تعاقــد مــع املدعــى عليــه لعمــل‬\n      ‫رفــع مســاحي علــى قطعــة أرض ميلكهــا بأجــرة قدرهــا ألــف وخمســمائة‬\n      ‫ريــال ليتمكــن مــن تقــدمي طلــب حجــة اســتحكام عليهــا باحملكمــة‬\n      ‫وأنــه قــام بعمــل الرفــع املســاحي وتقــدم بــه لــدى احملكمــة ولــم يقبــل‬\n      ‫ويطلــب إلــزام املدعــى عليــه بعمــل رفــع مســاحي لقطعــة األرض يقبــل‬\n      ‫لــدى احملكمــة ‪ -‬جــرى إفهــام املدعــي بتحريــر دعــواه ببيــان مواصفــات‬\n      ‫الرفــع املســاحي املدعــى بــه ‪ -‬أجــاب املدعــي بــأن دعــواه محــرره وال يعلــم‬\n      ‫املواصفــات املقبولــة لــدى احملكمــة هكــذا أجــاب ‪ -‬مبــا أن املدعــي‬\n      ‫امتنــع عــن حتريــر دعــواه وبنــاء علــى املــادة ‪ 1/ 63‬مــن نظــام املرافعــات‬\n\n‫‪23‬‬\n\f‫الشــرعية والئحتــه التنفيذيــة ونصهــا ( إذا امتنــع املدعــي عــن حتريــر‬\n‫دعــواه أو عجــز عنــه فعلــى القاضــي أن يحكــم بصــرف النظــر عــن‬\n‫الدعــوى حتــى حتريرهــا‪ - )..‬صــدر احلكــم بصــرف النظــر عــن الدعــوى‬\n‫حتــى حتريرهــا وأن هــذا احلكــم لفصــل النــزاع وال يكفــي إلثبــات‬\n‫التملــك وال يقــوم مقــام حجــة االســتحكام وال يســتند عليــه يف اإلفــراغ‬\n‫‪ -‬قنــع املدعــى عليــه باحلكــم واعتــرض املدعــي بــدون الئحــة ‪ -‬صــدق‬\n                    ‫احلكــم مــن محكمــة االســتئناف مبنطقــة القصيــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة الــرس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة الــرس برقــم ‪ 34476708‬وتاريــخ‬\n‫‪1434/10/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342431098‬وتاريــخ‬\n‫‪1434/10/27‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/11/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 00‬وفيها حضر ‪.......‬ســعودي بالســجل املدني رقم‬\n‫‪.......‬وادعــى علــى احلاضــر معــه ‪.......‬ســعودي بالســجل املدنــي رقــم ‪.......‬‬\n‫قائــا يف دعــواه أنــه منــذ ســنة ونصــف تقريبــا مــن تاريــخ اليــوم تعاقــدت‬\n‫مــع املدعــى عليــه علــى أن يقــوم بعمل رفع مســاحي لقطعة أرض أملكها‬\n‫تقــع يف مركــز ‪.......‬ألمتكــن مــن تقــدمي طلــب حجــة اســتحكام علــى‬\n‫قطعــة األرض املذكــورة للمحكمــة العامــة مبحافظــة الــرس وتعاقــدت‬\n‫مــع املدعــى عليــه أن يعمــل الرفــع املســاحي املذكــور بأجــره قدرهــا ألــف‬\n‫وخمســمائة ريــال ســلمتها للمدعــى عليــه وقــام املدعــى عليــه بعمــل رفــع‬\n‫مســاحي لقطعــة األرض املذكــورة وقدمــت الرفــع املســاحي املذكــور‬\n\n                                                                                     ‫‪24‬‬\n\f     ‫للمحكمــة ولــم ُيقبــل لــذا أطلــب إلــزام املدعــى عليــه بعمــل رفــع مســاحي‬\n     ‫ُيقبــل لــدى احملكمــة لقطعــة األرض املذكــورة هكــذا ادعــى وبعــد‬\n     ‫ســماع الدعــوى وقبــل ســؤال املدعــى عليــه عــن الدعــوى ومبــا أن الدعــوى‬\n     ‫غيــر محــررة وبنــاء علــى املــادة رقــم ‪ 63‬مــن نظــام املرافعــات الشــرعية‬\n     ‫ونصهــا ( علــى القاضــي أن يســأل املدعــي عمــا هــو الزم لتحريــر دعــواه‬\n     ‫قبــل اســتجواب املدعــى عليــه وليــس لــه ردهــا لتحريرهــا وال الســير‬\n     ‫فيهــا قبــل ذلــك ) أ‪.‬ه ـ لــذا فقــد طلبــت مــن املدعــي حتريــر دعــواه وذلــك‬\n     ‫ببيــان مواصفــات الرفــع املســاحي املدعــى بــه فأجــاب املدعــي بقولــه‬\n     ‫دعــواي محــررة وأنــا ال أعــرف مواصفــات الرفــع املســاحي املقبــول لــدى‬\n     ‫احملكمــة هكــذا أجــاب ومبــا أن املدعــي امتنــع عــن حتريــر دعــواه‬\n     ‫وبنــاء علــى املــادة رقــم ‪ 1/63‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n     ‫التنفيذيــة ونصهــا ( إذا امتنــع املدعــي عــن حتريــر دعــواه أو عجــز عنــه‬\n     ‫فعلــى القاضــي أن يحكــم بصــرف النظــر عــن الدعــوى حتــى حتريرهــا‬\n     ‫ويعامــل مــن لــم يقنــع بتعليمــات التمييــز ) أ‪.‬ه ـ لــذا فقــد حكمــت بصرف‬\n     ‫النظــر عــن الدعــوى حتــى حتريرهــا وهــذا احلكــم لفصــل النــزاع ال‬\n     ‫يكفــي إلثبــات التملــك وال يقــوم مقــام حجــة االســتحكام وال يســتند‬\n     ‫عليــه يف أي إفــراغ وبعــد النطــق باحلكــم وتالوتــه عليهمــا أفهمتهمــا‬\n     ‫بطــرق االعتــراض املقــررة ومواعيدهــا فقــرر املدعــى عليــه قناعتــه وقــرر‬\n     ‫املدعــي عــدم قناعتــه وطلــب رفــع احلكــم حملكمــة االســتئناف بــدون‬\n     ‫مذكــرة اعتراضيــة واختتمــت اجللســة الســاعة ‪ 08 : 20‬وبــاهلل التوفيــق‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬وحــرر يف‬\n     ‫‪1434/11/11‬ه ـ احلمــد هلل وحــده وبعــد يف هــذا اليــوم اخلميــس املوافــق‬\n     ‫‪1434/12/26‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 00‬واملعاملــة قــد عــادت‬\n\n\n‫‪25‬‬\n\f‫مــن محكمــة االســتئناف بالقصيــم وقــد مت التظهيــر علــى صــك احلكــم‬\n‫بقــرار الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة القصيــم‬\n‫رقــم ‪ 34374956‬وتاريــخ ‪1434/12/1‬ه ـ نصــه ( تظهيــرات الدائــرة‬\n‫احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة القصيــم احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34358756‬وتاريــخ‬\n‫‪1434/11/12‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ ...‬وأصدرنــا القــرار رقــم‬\n‫‪ 34374956‬وتاريــخ ‪1434/12/1‬ه ـ املتضمــن املصادقــة علــى احلكــم ‪.‬‬\n‫وإذا حــرر املدعــي دعــواه فــإن علــى فضيلتــه إجــراء الــازم وفــق مــا جــاء‬\n‫يف املــادة ‪ 2/63‬مــن نظــام املرافعــات الشــرعية قاضــي اســتئناف ‪.......‬‬\n‫قاضــي اســتئناف ‪.......‬رئيــس الدائــرة د‪ )....... .‬أ‪ .‬ه ـ واختتمــت اجللســة‬\n‫الســاعة ‪ 08 : 05‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/25‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫ال ـمـ ــحكمة الـ ـع ــام ـ ــة مبحافظــة الــرس ب ــرق ـ ــم ‪ 342431098‬وتــاري ـ ــخ‬\n‫‪1434/11/19‬هـ ؛ احملالة إلينا برقم ‪ 34523794‬الــمرف ــق بها ال ـصــك‬\n‫الــمسج ـ ــل ب ــرق ـ ــم ‪ 34358756‬وت ــاريـ ـ ــخ ‪1434/11/12‬هــ؛ الصــادر‬\n‫مــن فضيلــة الشــيخ‪....... /‬باحملكمــة؛ اخلــاص بدعــوى‪....... /‬ضــد‪/‬‬\n‫‪ ،.......‬بشــأن املطالبــة بعمــل رفــع مســاحي لقطعــة االرض املذكــورة يف‬\n‫الدعــوى ي ـ ُقـبـ َــل لــدى احملكمــة ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫بصــرف النظــر عــن الدعــوى حتــى حتريرهــا؛ علــى النحــو املفصــل فيــه‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n\n\n                                                                                        ‫‪26‬‬\n\f     ‫احلكــم وإذا حــرر املدعــي دعــواه فــإن علــى فضيلتــه إجــراء الــازم وفــق‬\n     ‫ماجــاء يف املــادة ‪ 2/63‬مــن نظــام املرافعــات الشــرعية‪ .‬واهلل املوفــق‪،‬‬\n                           ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f28\n\f29\n\f30\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":23,"source_page_end":30,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"eb068e82f61135a0916ce91cc9f0167c73577101faebe4f28b91bbc08634d64e","normalized_text_hash":"9979bedcd49234dbff5a25ea920379a6f1124598dfb5efdcbf5628a6757800d7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p23-34358756"},{"id":"8d4e0bea-e9d5-5afd-8931-61beb238cf9a","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -تعويض -طلب رفع اسم من القائمة السوداء -طعن يف مديونية رقم مسجل من شركة اتصاالت -طلب تعويض عن مصاريف دعوى -دفع بعدم االختصاص -صرف النظر لعدم","document_number":"3417867","case_number":"51152","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنظر القضية وأنها من اختصاص هيئة االتصاالت -جرى الرجوع لنظام االتصاالت الصادر باملرسوم امللكي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"اختصاص -تعويض -طلب رفع اسم من القائمة السوداء -طعن يف مديونية رقم مسجل من شركة اتصاالت -طلب تعويض عن مصاريف دعوى -دفع بعدم االختصاص -صرف النظر لعدم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/1/20 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3417867 :‬‬\n                           ‫َر ْق ُم الدعوى‪51152 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34185224‬تاريخه‪1434/4/10:‬هـ‬\n\n\n     ‫اختصــاص‪ -‬تعويــض‪ -‬طلــب رفــع اســم مــن القائمــة الســوداء‪ -‬طعــن‬\n     ‫يف مديونيــة رقــم مســجل مــن شــركة اتصــاالت ‪ -‬طلــب تعويــض‬\n     ‫عــن مصاريــف دعــوى‪ -‬دفــع بعــدم االختصــاص‪ -‬صــرف النظــر لعــدم‬\n                                                             ‫االختصــاص ‪.‬‬\n\n\n\n\n     ‫نظــام االتصــاالت الصــادر باملرســوم امللكــي رقــم م‪ 12/‬يف ‪1422/3/12‬ه ـ‬\n     ‫واملــادة العاشــرة منــه ونصهــا ( تتولــى هيئــة االتصــاالت توفيــر احلمايــة‬\n     ‫للمســتخدمني واملشــغلني وحتــدد الالئحــة إجــراءات تســوية اخلالفــات‬\n     ‫بــن املشــغلني أنفســهم أو مــا بينهــم وبــن املســتخدمني مبــا يف ذلــك‬\n     ‫اعتــراض املســتخدمني علــى املبالــغ الــواردة يف الفواتير أو على مســتوى‬\n                                                                       ‫اخلدمــة )‪.‬‬\n\n\n\n     ‫تقــدم املدعــي بدعــوى ضــد أحــد مشــغلي شــبكة االتصــاالت بأنــه‬\n     ‫تفاجــأ بــإدراج اســمه يف القائمــة الســوداء لوجــود مديونيــة مســجلة عليــه‬\n     ‫بغيــر حــق حيــث قــام مبراجعــة الشــركة فظهــر وجــود رقــم مســجل عليــه‬\n     ‫ال يعــود لــه‪ ،‬وأشــار يف دعــواه أنــه فقــد بطاقتــه الشــخصية قبــل ســنوات‬\n     ‫وبلــغ عــن فقدهــا‪ ،‬وقــد أقــر وكيــل املدعــى عليــه بتســجيل املديونيــة‬\n     ‫علــى املدعــي وإدراج اســمه يف القائمــة الســوداء‪ ،‬ودفــع بعــدم اختصــاص‬\n‫‪31‬‬\n\f‫احملكمــة العامــة بنظــر القضيــة وأنهــا مــن اختصــاص هيئــة االتصــاالت‬\n‫‪ -‬جــرى الرجــوع لنظــام االتصــاالت الصــادر باملرســوم امللكــي رقــم‬\n‫م‪ 12/‬يف ‪1422/3/12‬ه ـ واملــادة العاشــرة منــه ونصهــا ( تتولــى هيئــة‬\n‫االتصــاالت توفيــر احلمايــة للمســتخدمني واملشــغلني وحتــدد الالئحــة‬\n‫إجــراءات تســوية اخلالفــات بــن املشــغلني أنفســهم أو مــا بينهــم وبــن‬\n‫املســتخدمني مبــا يف ذلــك اعتــراض املســتخدمني علــى املبالــغ الــواردة يف‬\n‫الفواتيــر أو علــى مســتوى اخلدمــة) ‪ ،‬وعليــه قــررت الدائــرة صــرف النظــر‬\n‫عــن دعــوى املدعــي لعــدم االختصــاص ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                   ‫االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...............‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪51152‬وتاريــخ ‪ 1431/12/02‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 31202452‬وتاريــخ ‪ 1431/12/02‬ه ـ ويف يــوم االحــد‬\n‫املوافق‪1432/03/17‬هـ فتحت اجللســة وفيها حضر ‪..................‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم ‪ .................‬وادعــى علــى احلاضــر معــه‬\n‫‪ ..................‬حامــل الســجل املدنــي رقــم ‪ ...............‬بصفتــه وكيــا عــن‬\n‫‪ ....................‬بصفتــه رئيــس مجلــس إدارة شــركة ‪ ...................‬وبصفتــه‬\n‫وكيــا عــن أعضــاء مجلــس ‪.........................‬بالوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة بالريــاض برقــم ‪ 55769‬وتاريــخ ‪1427/05/29‬ه ـ‬\n‫جلــد ‪ 14703‬املخــول لــه فيهــا باملرافعــة واملدافعــة واملطالبــة واملخاصمــة‬\n‫واالقــرار قائــا يف دعــواه إنــه يف عــام ‪1423‬ه ـ فقــدت بطاقــة األحــوال‬\n\n                                                                                       ‫‪32‬‬\n\f     ‫بالرقــم ‪ .........‬وقمــت باإلبــاغ عــن ذلــك لــدى شــرطة منفوحــة فــور‬\n     ‫فقدانهــا ثــم قمــت بإصــدار بــدل فاقــد لبطاقــة األحــوال وتقدمــت‬\n     ‫لشــركة‪ ......................‬واســتصدرت شــريحه جــوال ثــم بعــد فتــرة‬\n     ‫فوجئــت بقطعهــا دون ســابق علــم أو إنــذار ومبراجعــة الشــركة أفادونــي‬\n     ‫بــأن علــي مديونيــة علــى الرقــم الثابــت رقــم ‪ .........‬مببلــغ إجمالــي قــدره‬\n     ‫تســعه وعشــرون ألفــا وســتمائة وخمســة وخمســون ريــال وأنــا ال عالقــة‬\n     ‫لــي بهــذا الرقــم وهــذه املديونيــة وإمنــا أصــدرت مــن خــال بطاقتــي‬\n     ‫املفقــودة وقــد تضــررت مــن ذلــك ووضــع اســمي يف قوائــم الســداد‬\n     ‫املتعثــرة لــدى شــركة ‪ ....‬ولــدى البنــوك التجاريــة ولــم أســتطع اســتخراج‬\n     ‫قــرض أو نحــو ذلــك لــذا أطلــب إســقاط املديونيــة عنــي وشــطب اســمي‬\n     ‫مــن القوائــم املاليــة احملظــورة لــدى شــركة ‪ ....‬ولــدى البنــوك التجاريــة‬\n     ‫هــذه دعــواي‪ ،‬وبــرد ذلــك علــى املدعــى عليــه وكالــة أجــاب بقولــه ال‬\n     ‫علــم لــي بدعــوى املدعــي وأطلــب إمهالــي ملراجعــة موكلتــي واالستفســار‬\n     ‫مــن ذلــك لــذا رفعــت اجللســة لذلــك ثــم يف جلســة أخــرى حضــر الطرفــان‬\n     ‫وبســؤال املدعــى عليــه وكالــة عــن الدعــوى أبــرز إجابــة هــذا نصهــا قبــل‬\n     ‫الدخــول يف الــرد ‪ ،‬وددت أن أوضــح لفضيلتكــم طبيعــة العالقــة بــن‬\n     ‫املدعــي وموكلتــي وأســاس العالقــة بــن طــريف الدعــوى ‪ ،‬حيــث أن‬\n     ‫العالقــة منشــأها عقــد تقــدمي خدمــات اتصــاالت ‪ ،‬باعتبــار أن املدعــي‬\n     ‫هــو (مســتخدم اخلدمــة ) وموكلتــي هــي (مقدمــة اخلدمــة أو املشــغل ) ‪،‬‬\n     ‫وبالرجــوع إلــى موكلتــي ومراجعــة الطلــب أوضــح لفضيلتكــم اآلتــي‬\n     ‫‪-:‬تقــدم املدعــي ملوكلتــي بطلــب تأســيس هاتــف ثابــت ‪ ،‬وقــد مت ذلــك‬\n                         ‫وأســس للمذكــور هاتــف ثابــت يحمــل الرقــم (‪.).......‬‬\n     ‫‪ -‬مبراجعــة مســوغات التأســيس اتضــح لدينــا وجــود عقــد اشــتراك يف‬\n\n\n‫‪33‬‬\n\f‫خدمــات االتصــاالت مقــدم مــن قبــل املدعــي ويحمــل توقيعــه وكافــة‬\n‫بياناتــه ومرفــق بــه نســخة مــن بطاقــة أحــوال املدعــي ‪ -.‬فيمــا يتعلــق‬\n‫مبــا اوضحــه املدعــي مــن فقدانــه لبطاقــة أحوالــه وهــو مــا مت مبوجبــه‬\n‫تأســيس الهاتــف (حســب ادعائــه) ‪ ،‬تدفــع موكلتــي بــأن هــذا االدعــاء‬\n‫غيــر صحيــح ‪ ،‬حيــث أن موكلتــي ليســت جهــة أمنيــة أو بنكيــة تتوافــر‬\n‫لديهــا كافــة بيانــات املواطنــن ‪ ،‬حيــث أنــه مبجــرد تقــدم العميــل وتعبئة‬\n‫الطلبــات وإرفــاق الهويــة بعــد التأكــد منهــا مــن قبــل املوظــف املختــص‬\n‫تتــم خدمتــه ‪ .‬وتؤكــد موكلتــي ســامة موقفهــا النظامــي واإلجرائــي ‪،‬‬\n‫وصحــة تأســيس الهاتــف املشــار إليــه‪ ،‬ونوضــح لفضيلتكــم أن املدعــي‬\n‫كان يعلــم عــن تأســيس الهاتــف منــذ مــدة طويلــه (حســب إفادتــه يف‬\n‫اجللســة األولــى) إال أنــه لــم يتقــدم باعتراضــه إال بعــد مــا يقارب ‪ 8‬ســنوات‬\n‫‪ ،‬حيــث كان حريـ ًا بــه يف حــال صحــة ادعــاءه التقــدم أمام احملكمة يف‬\n‫حينــه‪ ،‬مــع العلــم انــه ال يوجــد أي مانــع مينعــه مــن االعتــراض فســكوته‬\n‫قبــول ورضــاء منــه بصحــة اخلدمــة التــي قدمــت لــه‪ ،‬والقاعــدة الشــرعية‬\n‫تنــص ( الســكوت يف معــرض احلاجــة إلــى بيــان بيــان) (وال ينســب إلــى‬\n                                                                 ‫ســاكت قــول ) ‪.‬‬\n        ‫بناء على ما تقدم أطلب من فضيلتكم ما يلي ‪:‬‬          ‫صاحب الفضيلة ‪ً ..‬‬\n                ‫بناء على ما سبق ذكره ‪.‬‬      ‫‪ .1‬رد دعوى املدعي لعدم صحتها ً‬\n‫ا والبالــغ قــدره‬    ‫‪ .2‬إلــزام املدعــي بتســديد املبلــغ املتحقــق عليــه كام ـ ً‬\n‫(‪ )29.655.13‬تســعة وعشــرون ألفـ ًا وســتمائة وخمســة وخمســون ريــا ًال‬\n                   ‫وثالثــة عشــر هللــه لصالــح موكلتــي شــركة ‪.................‬‬\n‫‪ .3‬إلــزام املدعــي بدفــع مبلــغ وقــدره (‪ )10.000‬عشــرة آالف ريــال لصالح‬\n‫موكلتــي كتعويــض عــن قيمــة مصاريــف الدعــوى ا‪.‬ه ـ وبعرضهــا علــى‬\n\n\n                                                                                       ‫‪34‬‬\n\f     ‫املدعــي قــال أطلــب اإلمهــال ثــم يف جلســة أخــرى حضــر الطرفــان‬\n     ‫وبســؤال املدعــى عليــه وكالــة عمــا اســتمهل مــن أجلــه أبــرز إجابــة‬\n     ‫محــررة هــذا نصهــا حيــث أن العالقــة منشــأها عقــد تقــدمي خدمــات‬\n     ‫اتصــاالت ‪ ،‬باعتبــار أن املدعــي هــو (مســتخدم اخلدمــة ) وموكلتــي‬\n     ‫هــي (مقدمــة اخلدمــة أو املشــغل ) واجلهــة التــي تنظــم هــذه العالقــة هــي‬\n     ‫هيئــة االتصــاالت وتقنيــة املعلومــات وهــذه العالقــة منظمــة وفــق أنظمــة‬\n     ‫ولوائــح وهــي ‪ -:‬تنظيــم هيئــة االتصــاالت وتقنيــة املعلومــات الصــادر‬\n     ‫بقــرار مجلــس الــوزراء رقــم ‪ 74‬وتاريــخ ‪1422/3/5‬ه ـ ‪ ،‬واملعــدل بقــرار‬\n     ‫املجلــس رقــم ‪ 133‬وتاريــخ ‪1424/5/21‬ه ـ حيــث نصــت املــادة الثانيــة‬\n     ‫مــن هــذا التنظيــم اختصاصــات هيئــة االتصــاالت ‪ -.‬نظــام االتصــاالت‬\n     ‫الصــادر بقــرار مجلــس الــوزراء رقــم ‪ 74‬وتاريــخ ‪1422/3/5‬ه ـ املقــر‬\n     ‫مبوجــب املرســوم امللكــي رقــم م‪12/‬وتاريــخ ‪1422/3/12‬ه ـ ‪ -‬الالئحة‬\n     ‫التنفيذيــة لنظــام االتصــاالت الصــادرة بقــرار معالــي وزيــر البــرق والبريد‬\n     ‫والهاتــف رقــم (‪ )11‬وتاريــخ ‪1423/5/17‬ه ـ وعليــه تتقــدم موكلتــي‬\n     ‫بدفوعهــا الشــكلية واملوضوعيــة مســتندة فيهــا إلــى هــذه األنظمــة‬\n                     ‫واللوائــح التــي اشــرنا إليهــا وذلــك وفــق التفصيــل التالــي ‪:‬‬\n     ‫الدفــع الشــكلي ‪ :‬تدفــع موكلتــي بعــدم اختصــاص القضــاء الشــرعي‬\n                        ‫بنظــر هــذا النــوع مــن الدعــاوى وذلــك لألســباب التاليــة ‪:‬‬\n     ‫أ‪ .-‬نصــت املــادة العاشــرة مــن نظــام االتصــاالت علــى أن « تتولــى الهيئــة‬\n     ‫توفيــر احلمايــة للمســتخدمني واملشــغلني وحتــدد الالئحــة إجــراءات‬\n     ‫تســوية اخلالفــات بــن املشــغلني أنفســهم أو بينهــم وبــن املســتخدمني مبــا‬\n     ‫يف ذلــك اعتــراض املســتخدمني علــى املبالــغ الــواردة يف الفواتيــر أو علــى‬\n                                                                 ‫مســتوى اخلدمــة» ‪. .‬‬\n\n\n‫‪35‬‬\n\f‫ب‪ -‬نرفــق لفضيلتكــم ســابقة قضائيــة بالصــك رقــم ‪ ........‬وتاريــخ‬\n‫‪1432/6/20‬ه ـ املؤيــد مــن الدائــرة احلقوقيــة السادســة مبحكمــة‬\n‫االســتئناف بالريــاض بالقــرار رقــم ‪/261‬ق‪/‬أ وتاريــخ ‪ 1432/9/16‬ه ـ‬\n‫يؤكــد لفضيلتكــم عــدم اختصــاص احملكمــة النوعــي بنظــر مثل هذه‬\n‫الدعــاوى اســتناد ًا علــى املــادة رقــم (‪ )72‬مــن نظــام املرافعــات الشــرعية ‪.‬‬\n                                                                  ‫الدفع املوضوعي ‪:‬‬\n‫أوال‪ :‬تتمســك موكلتــي مبــا ســبق تقدميــه يف مذكرتهــا املؤرخــة يف‬\n                           ‫‪1432/8/2‬ه ـ ومــا جــاء فيهــا مــن دفــوع موضوعيــة ‪.‬‬\n‫ثاني ـ ًا ‪ :‬بشــأن طلبــات املدعــي الــواردة يف مذكرتــه املقدمــة يف جلســة‬\n                         ‫يــوم الثالثــاء ‪1432/11/20‬ه ـ تدفــع موكلتــي باآلتــي‪:‬‬\n‫‪ -‬بشــأن طلــب املدعــي نســخة كاملــة مــن عقــد التأســيس نفيــد‬\n                      ‫فضيلتكــم بأنــه ســبق تقدميــه يف اجللســة الســابقة ‪.‬‬\n‫‪ -‬بشــأن مــا افــاد بــه املدعــي مــن عــدم اعتراضــه طيلــة الســنوات املاضيــة‬\n‫لعــدم وجــود مــن يوجهــه يف ذلــك احلــن فهــذا الدفــع غيــر مقبــول اطالقـ ًا‬\n‫وال ميكــن االعتــداد بــه والقاعــدة الشــرعية تنــص ( الســكوت يف‬\n‫معــرض احلاجــة إلــى بيــان بيــان ) و ( ال ينســب إلــى ســاكت قــول)‪.‬‬\n‫ـاء علــى مــا تقــدم أطلــب مــن فضيلتكــم مــا يلــي ‪:‬‬   ‫صاحــب الفضيلــة ‪ ..‬بنـ ً‬\n                   ‫بناء على ما سبق ذكره‬      ‫‪ .1‬رد دعوى املدعي لعدم صحتها ً‬\n‫ا والبالــغ قــدره‬     ‫‪ .2‬إلــزام املدعــي بتســديد املبلــغ املتحقــق عليــه كام ـ ً‬\n‫(‪ )29.655.13‬تســعة وعشــرون ألفـ ًا وســتمائة وخمســة وخمســون ريــا ًال‬\n           ‫وثالثــة عشــر هللــه لصالــح موكلتــي شــركة ‪...........................‬‬\n‫‪ .3‬إلــزام املدعــي بدفــع مبلــغ وقــدره (‪ )10.000‬عشــرة آالف ريــال لصالح‬\n                           ‫موكلتــي كتعويــض عــن قيمــة مصاريــف الدعوى ا‪.‬هـ‬\n\n\n                                                                                        ‫‪36‬‬\n\f     ‫وبعرضهــا علــى املدعــي قــال إن هــذا الــرد ال يحتــوي علــى مــا طلبــت منــه‬\n     ‫يف اجللســة املاضيــة وهــي عقــد التأســيس ومذكــور فيــه تاريــخ العقــد‬\n     ‫وتأسيســه وجهــات االتصــال والفواتيــر إال أنــه لــم يــأت بشــيء منهــا‬\n     ‫كمــا أن عقــد االشــتراك عليــه توقيــع منســوب لــي وهــو غيــر صحيــح‬\n     ‫ولــم أوقــع عليــه وأطلــب رفعــه لألدلــة اجلنائيــة للتحقــق مــن ذلــك وبعرضــه‬\n     ‫علــى املدعــى عليــه وكالــة قــال هــذا كل مــا لــدي وأكتفــي مبــا قدمــت‬\n     ‫وللتأمــل رفعــت اجللســة ثــم يف جلســة أخــرى يــوم الســبت ‪1434/1/17‬ه ـ‬\n     ‫لــدي أنــا ‪ ....................‬القاضــي باحملكمــة العامــة بالريــاض واخللــف‬\n     ‫لفضيلــة القاضــي ‪ ...................‬فتحــت اجللســة وفيهــا حضــر املدعــي‬\n     ‫واملدعــى عليــه وكالــة وقــد جــرى االطــاع علــى مــا ســبق ضبطــه وتلــي‬\n     ‫علــى الطرفــن فصادقــا عليــه وقــد جــرى االطــاع علــى نظــام االتصاالت‬\n     ‫الصــادر باملرســوم امللكــي رقــم م‪ 12/‬يف ‪1422/3/12‬ه ـ واملــادة‬\n     ‫العاشــرة منــه التــي تنــص علــى تولــي هيئــة االتصــاالت توفيــر احلمايــة‬\n     ‫للمســتخدمني واملشــغلني وحتدد الالئحة إجراءات تســوية اخلالفات بني‬\n     ‫املشــغلني أنفســهم أو مــا بينهــم وبــن املســتخدمني مبــا يف ذلــك اعتــراض‬\n     ‫املســتخدمني علــى املبالــغ الــواردة يف الفواتيــر أو علــى مســتوى اخلدمــة‬\n     ‫وبعــد االطــاع علــى الئحــة النظــام وحيــث ظهــر أن احملكمــة العامــة ال‬\n     ‫واليــة لهــا يف نظــر هــذه الدعــوى باعتبــار وجــود جهــة تختــص بنظرهــا يف‬\n     ‫النظــام فقــد حكمــت بصــرف النظــر عــن الدعــوى لعــدم االختصــاص‬\n     ‫وبعــرض احلكــم علــى الطرفــن قنــع بــه املدعــى عليــه وقــرر املدعــي أنــه‬\n     ‫لــم يقنــع وطلــب رفــع احلكــم حملكمــة االســتئناف دون الئحــة وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                             ‫حــرر يف ‪1434/1/17‬ه‬\n\n\n‫‪37‬‬\n\f‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/05/19‬ه ـ لــدي أنــا‬\n‫‪ ........................‬القاضــي باحملكمــة العامــة بالريــاض افتتحــت اجللســة‬\n‫وكانــت املعاملــة قــد عــادت مــن محكمــة االســتئناف بالريــاض برقــم‬\n‫‪ 34676305‬يف ‪1434/4/16‬ه ـ وقــد دون علــى ظهــر الصــك الصــادر يف‬\n‫القضيــة مــا نصــه ‪ ،‬احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك‬\n‫رقــم ‪ 3417867‬يف ‪1434/01/20‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة العامــة بالريــاض الشــيخ ‪ .....................‬وأصدرنــا القــرار‬\n‫رقــم ‪34185224‬يف ‪1434/04/10‬ه ـ املتضمــن أنــه لــم يظهــر مــا يوجــب‬\n      ‫االعتــراض وللبيــان حــرر‪ ،‬واهلل املوفــق حــرر يف ‪1434/05/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n‫‪ 31/202452‬وتاريــخ ‪1434/3/15‬ه املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ........................./‬املســجل برقــم‬\n‫‪ 3417867‬وتاريــخ ‪1434/1/20‬ه ـ اخلــاص بدعــوى ‪ ................... /‬ضــد‬\n‫ا عــن أعضــاء مجلس إدارة شــركة ‪ ......‬يف مبلغ‬            ‫‪......................../‬وكيـ ً‬\n‫مالــي علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم فضيلتــه بصرف‬\n‫النظــر عــن الدعــوى لعدم االختصاص‪ ،‬وبدراســة الصك وصورة ضبطه‬\n‫وأوراق املعاملــة قررنــا أنــه لــم يظهــر مــا يوجــب االعتــراض ‪ .‬والل ــه املوفــق‬\n                          ‫وصلــى اهلل علــى نبينــا محمـ ــد وآل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n                                                                                             ‫‪38‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":31,"source_page_end":38,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1fd50986e57e00439d818665166c5e1e5821dec41bdd68af49a77af892955be8","normalized_text_hash":"9a8cd96a7b7f8d7891473fa2b81c537fa7f13b9960d50b780636cb5d8ab93492","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p31-3417867"},{"id":"333cb0a4-bc6d-5586-b8b4-40665931de39","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص-عقار -أرض زراعية -قيام شركة الكهرباء بوضع أعمدة كهرباء على األرض -طلب إزالة األعمدة والتعويض عن فترة بقاء األعمدة باألرض -الدفع بعدم االختصاص الوالئي -عدم قبول الدعوى لعدم االختصاص -احلق يف إقامة الدعوى لدى اجلهة املختصة .","document_number":"347226","case_number":"32484539","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":"الدائرة احلقوقية الثانية برقم 34341640يف 1434/10/27ه ونص","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/10","year":"1434","subject":"اختصاص-عقار -أرض زراعية -قيام شركة الكهرباء بوضع أعمدة كهرباء على األرض -طلب إزالة األعمدة والتعويض عن فترة بقاء األعمدة باألرض -الدفع بعدم االختصاص الوالئي -عدم قبول الدعوى لعدم االختصاص -احلق يف إقامة الدعوى لدى اجلهة املختصة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك ‪ 347226 :‬تاريخه ‪1434/1/10 :‬هـ‬\n                        ‫رقم الدعوى ‪32484539 :‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n     ‫االستئناف‪ 342332529:‬تاريخه‪1434/11/10:‬هـ‬\n\n\n      ‫اختصاص‪-‬عقــار‪ -‬أرض زراعيــة ‪ -‬قيــام شــركة الكهربــاء بوضــع أعمــدة‬\n      ‫كهربــاء علــى األرض ‪ -‬طلــب إزالــة األعمــدة والتعويــض عــن فتــرة‬\n      ‫بقــاء األعمــدة بــاألرض ‪ -‬الدفــع بعــدم االختصــاص الوالئــي ‪ -‬عــدم‬\n      ‫قبــول الدعــوى لعــدم االختصــاص ‪ -‬احلــق يف إقامــة الدعــوى لــدى‬\n                                                            ‫اجلهــة املختصــة ‪.‬‬\n\n\n\n      ‫الفقــرة ( أ ) مــن البنــد ثاني ـ ًا مــن املــادة الثالثــة عشــرة مــن نظــام‬\n      ‫الكهربــاء الصــادر باملرســوم امللكــي رقــم ( م ‪ ) 56 /‬يف ‪1426/10/20‬ه ـ‬\n      ‫والتــي تقضــي باختصــاص جلنــة فــض منازعــات صناعــة الكهربــاء‬\n      ‫بالفصــل يف املنازعــات والشــكاوى واملخالفــات التــي تنشــأ مــن صناعــة‬\n                                                                           ‫الكهربــاء‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي أصالــة ووكالــة بأنــه وموكليــه ميلكــون قطعــة أرض‬\n      ‫زراعيــة ( ذكــر وصفهــا ) مبوجــب صــك حجــة اســتحكام ( ذكــر‬\n      ‫رقمــه وتاريخــه) وقــد قامــت شــركة الكهربــاء بوضــع ســتة أعمــدة‬\n      ‫كهربــاء يف اجلهــة اجلنوبيــة مــن األرض مــن عــام ‪1403‬ه ـ إلــى تاريخــه ‪،‬‬\n      ‫وقــد طلــب املدعــى إلــزام شــركة الكهربــاء بإزالــة جميــع هــذه األعمــدة‬\n\n‫‪39‬‬\n\f‫مــن األرض وإلزامهــا بالتعويــض عــن جميــع الفتــرة التــي ظلــت بهــا أعمدة‬\n‫الكهرباء‪،‬وقــد دفــع وكيــل شــركة الكهربــاء بعــدم االختصــاص‬\n‫حيــث إن األضــرار الناجتــة مــن صناعــة الكهربــاء مــن اختصــاص‬\n‫جلنــة فــض منازعــات صناعــة الكهربــاء املشــكلة مبوجــب قــرار‬\n‫مجلــس الــوزراء رقــم ‪ 211‬يف ‪1427/8/18‬ه ـ ‪،‬لكــن أجــاب املدعــي‬\n‫أصالــة ووكالــة بــأن اللجنــة املذكــورة مختصــة فقــط باالشــتراكات‬\n‫والرســوم وليــس لهــا اختصــاص بالتعويــض اســتناد ًا ملــا ورد يف الفقــرة‬\n‫(أ) مــن البنــد الثانــي مــن املــادة (‪ )13‬مــن نظــام الكهربــاء والتــي تقضــي‬\n‫باختصــاص جلنــة منازعــات صناعــة الكهربــاء بالفصــل يف املنازعــات‬\n‫والشــكاوى واملخالفــات التــي تنشــأ مــن صناعــة الكهربــاء ‪ ،‬وحيــث إن‬\n‫أعمــدة الكهربــاء املذكــورة بدعــوى املدعــي مــن املــواد الناشــئة عــن صناعة‬\n‫الكهربــاء لــذا فقــد صــدر احلكــم بعــدم قبــول دعــوى املدعــي أصالــة‬\n‫ووكالــة لعــدم االختصــاص وجــرى إفهــام املدعــي بــأن لــه حــق إقامــه‬\n‫الدعــوى لــدى اجلهــة املختصــة وصــدق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بنجــران برقــم ‪ 32484539‬وتاريــخ ‪1432/10/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 321030470‬وتاريــخ ‪ 1432/08/10‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1433/03/16‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 40‬‬\n‫وفيهــا ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ســجل جنــران‬\n‫ا عــن ‪...‬و‪......‬و‪...‬مبوجب‬\n                         ‫يف ‪1405/12/22‬ه ـ أصالـ ًة عــن نفســه ووكيـ ً‬\n\n                                                                                     ‫‪40‬‬\n\f     ‫الوكالــة الصــادرة مــن كتابــة عــدل جنــران برقــم ‪970501011464‬‬\n     ‫يف‪1431/4/11‬ه ـ كمــا حضــر املدعى عليه وكالة ‪...‬ســعودي اجلنســية‬\n     ‫مبوجب الســجل املدني رقم ‪...‬ســجل خميس مشــيط يف ‪1421/3/11‬هـ‬\n     ‫ا عــن ‪...‬بصفتــه الوكيــل الشــرعي عــن أعضــاء‬          ‫حــال كونــه وكي ـ ً‬\n     ‫مجلــس إدارة الشــركة الســعودية للكهربــاء بالســجل التجــاري رقــم‬\n     ‫‪1010158683‬يف ‪1421/1/28‬ه ـ مبوجــب الوكالــة الصــادرة مــن‬\n     ‫كتابــة العــدل الثانيــة بالريــاض برقــم ‪57577‬يف ‪1431/8/1‬هـ ثم ادعى‬\n     ‫ا إننــي وموكلــي منلــك قطعــة األرض الزراعيــة الكائنــة يف‬     ‫املدعــي قائـ ً‬\n     ‫املعامــر بالشــرفة بنجــران ويحدهــا مــن الشــمال مجــرى مــاء يليــه مزرعــة‬\n     ‫ملــك ‪...‬بطــول ثمانيــة وتســعني متــر ًا وعشــرة ســنتمترات ‪98،10‬م ومــن‬\n     ‫اجلنــوب شــارع األميــر ســلطان بعــرض ثالثــن متــر ًا وبطــول مئتــن وســتة‬\n     ‫وخمســن متــر ًا وخمســة وســتني ســنتمترمربع‪ 256،65‬ومــن الشــرق‬\n     ‫شــارع ترابــي بعــرض أربعــة أمتــار ‪4‬م مــن ملــك الورثــة يليــه مزرعــة ملــك‬\n     ‫‪ ...‬بطــول يبــدأ مــن الشــمال ســتة عشــر متــر ًا وثالثــن ســنتمتر ًا ‪16،30‬م‬\n     ‫ثــم ينكســر للخــارج بزاويــة مئــة وإحــدى وثالثــن درجــة ‪ 131‬بطــول مئــة‬\n     ‫وســتة عشــر متر ًا وخمســة عشــر ســنتمتر ًا ‪ 116،15‬ثم ينكســر للداخل‬\n     ‫بزاويــة مئــة وســتة وســتني درجــة ‪ 166‬بطــول مئــة وثمانيــة أمتــار وخمســة‬\n     ‫عشــر ســنتمتر ًا ‪108،15‬م ثــم ينكســر للداخــل بزاويــة مئــة وإحــدى‬\n     ‫وســبعني درجــة ‪171‬وبطــول ســبعني متــر ًا وخمســة ســنتمتر ًا ‪70،05‬م ثــم‬\n     ‫ينكســر للخــارج بزاويــة مئــة وســبع وســبعني درجــة ‪ 177‬وبطــول مئــة‬\n     ‫وثالثــة وثالثــن متــر ًا وســبعني ســنتمتر ًا ‪133.70‬م ثــم ينكســر للخــارج‬\n     ‫بزاويــة مئــة وثالثــة وســبعني درجــة ‪ 173‬وبطــول مئــة واثنــن وســتني‬\n     ‫متــر وخمســة وثمانــن ســنتمتر‪ 162‬بزاويــة مئــة وســت وســتني درجــة‬\n\n\n‫‪41‬‬\n\f‫‪ 166‬وبطــول مئتــن واثنــن وثالثــن متــر ًا وخمســة وخمســن ســنتمتر ًا‬\n‫‪232،55‬م ثــم ينكســر للداخــل بزوايــة مئــة وتســعة وســبعني درجــة‬\n‫‪ 179‬وبطــول مئتــن وخمســة وثالثــن متــر ًا وخمســة وثمانــن ســنتمتر ًا‬\n‫‪235،85‬م ثــم ينكســر للداخــل بزاويــة مئــة وثمــان وســبعني درجــة‬\n‫‪ 178‬وبطــول مئتــن وأربعــة وســبعني متــر ًا وخمســة وخمســن ســنتمتر ًا‬\n‫‪274،55‬م بطــول إجمالــي للحــد الثالــث ســبعمائة واثنــن وأربعــن متــر ًا‬\n‫وخمســة وتســعني ســنتمتر ًا ‪742،95‬م بطــول إجمالــي للحــد الغربــي ألف‬\n‫ومئتــن وثمانيــة عشــر متــر ًا وأربعــن ســنتمتر ًا ‪1218،40‬م واملســاحة‬\n‫اإلجماليــة مئتــان وســتة ألــف وثمانيــة وعشــرون متــر ًا مربع ـ ًا وعشــرون‬\n‫ســنتمتر ًا ‪206028،20‬م‪ 2‬مبوجــب صــك حجــة االســتحكام الصــادر‬\n‫مــن هــذه احملكمــة برقــم ‪ 1/256‬يف ‪1428/1/1‬ه ـ وقــد قامــت موكلــة‬\n‫املدعــى عليــه شــركة الكهربــاء بوضــع ســتة أعمــدة كهربــاء يف اجلهــة‬\n‫اجلنوبيــة مــن عــام ‪1403‬ه ـ إلــى تاريخــه أطلــب إلــزام شــركة الكهربــاء‬\n‫موكلــة املدعــى عليــه بإزالــة جميــع هــذه األعمــدة مــن أرضنــا وإلزامهــا‬\n‫بتعويضنــا عــن جميــع الفتــرة التــي ظلــت بهــا أعمــدة الكهربــاء بأرضنــا‬\n‫ا‬ ‫هكــذا ادعــى وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائ ـ ً‬\n‫إن موكلتــي تدفــع بعــدم اختصــاص احملاكــم العامــة بالنظــر يف هــذه‬\n‫الدعــوى إذ يقــول املدعــي يف دعــواه أنهــم متضرريــن مــن وضــع موكلتــي‬\n‫لســتة أعمــدة كهربــاء بأرضهمــا وحيــث أن هــذه األضــرار ناجتــة مــن‬\n‫صناعــة الكهربــاء فــإن اجلهــة املنعقــد لهــا االختصــاص هــي جلنــة فــض‬\n‫منازعــات صناعــة الكهربــاء املشــكلة مبوجــب قــرار مجلــس الــوزراء‬\n‫‪ 211‬يف ‪1427/8/18‬ه ـ اســتناد ًا إلــى املــادة الثالثــة عشــرة مــن نظــام‬\n‫الكهربــاء الصــادر باملرســوم امللكــي(م‪ )56/‬يف ‪1426/10/20‬ه ـ‬\n\n\n                                                                                  ‫‪42‬‬\n\f     ‫هكــذا أجــاب ويف جلســة أخــرى حضــر الطرفــان وبســؤالهما هــل لــدى‬\n     ‫ا إن املدعــى عليــه‬ ‫أحدكمــا مــا يريــد إضافتــه فأجــاب املدعــي قائ ـ ً‬\n     ‫وكالــة دفــع بعــدم اختصــاص احملكمــة العامــة بنظــر هــذه الدعــوى‬\n     ‫وأن املختــص بذلــك هــي جلنــة فــض منازعــات الكهربــاء وبحســب علمــي‬\n     ‫فــإن هــذه اللجنــة مختصــة فقــط باالشــتراكات والرســوم وليــس لهــا‬\n     ‫أي اختصــاص بالتعويــض هكــذا أجــاب وبعرضــه علــى املدعــى عليــه‬\n     ‫ا إن اللجنــة مخولــة نظام ـ ًا بجميــع املنازعــات مبــا‬   ‫وكالــة أجــاب قائ ـ ً‬\n     ‫يف ذلــك طلبــات التعويــض وطلبــات اإلزالــة وللمدعــي حــق االعتــراض‬\n     ‫علــى القــرارات الصــادرة مــن هــذه اللجنــة أمــام ديــوان املظالــم هكــذا‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى واســتناد ًا ملــا ورد يف الفقــرة‬\n                                                                          ‫أجــاب فبنـ ً‬\n     ‫(أ) البنــد ثاني ـ ًا مــن املــادة الثالثــة عشــرة مــن نظــام الكهربــاء والتــي‬\n     ‫تقضــي باختصــاص جلنــة فــض منازعــات صناعــة الكهربــاء بالفصــل يف‬\n     ‫املنازعــات والشــكاوي واملخالفــات التــي تنشــأ مــن صناعــة الكهربــاء‬\n     ‫وحيــث أن أعمــدة الكهربــاء املذكــورة بدعــوى املدعــي مــن املــواد‬\n     ‫الناشــئة عــن صناعــة الكهربــاء فقــد قــررت عــدم قبــول دعــوى املدعــي‬\n     ‫أصالــة ووكالــة لعــدم االختصــاص وأفهمــت املدعــي أصالــة ووكالــة‬\n     ‫بــأن لــه حــق إقامــة الدعــوى لــدى اجلهــة املختصــة وبعــرض ذلــك علــى‬\n     ‫الطرفــن قــرر املدعــي أصالــة ووكالــة اعتراضــه علــى احلكــم بالئحــة‬\n     ‫اعتراضيــة كمــا قــرر املدعــى عليــه وكالــة قناعتــه باحلكــم وقــد‬\n     ‫أفهمــت املدعــي أصالــة ووكالــة بــأن عليــه تقــدمي الئحتــه االعتراضيــة‬\n     ‫خــال مــدة قدرهــا ثالثــون يومـ ًا مــن تاريــخ اســتالمه صــورة القــرار ففهــم‬\n     ‫ذلــك ورفعــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل وســلم علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/6/15‬هــ‪.‬‬\n\n\n‫‪43‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبوجــب خطابهــم رقــم ‪ 34117692‬وتاريــخ ‪1434/06/12‬ه ـ ومرفــق‬\n‫بهــا قــرار املالحظــة رقــم ‪ 34223557‬وتاريــخ ‪1434/05/27‬ه ـ ونــص‬\n‫احلاجــة منــه «وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ مــا يلــي ‪ :‬أوال ‪ /‬فضيلتــه نظــر يف الدعــوى قبــل‬\n‫االســتئذان يف نظرهــا مــن املقــام الســامي كــون اجلهــة املدعــى عليهــا‬\n‫تتبــع جهــة حكوميــة ثانيــا ‪ /‬باالطــاع علــى صــورة حجــة االســتحكام‬\n‫رقــم ‪ 1/256‬يف ‪1428/1/1‬ه ـ املرفقــة واملتعلقــة بتملــك املدعــن لم جند‬\n‫أنهــا مســتكملة لإلجــراءات النظاميــة حيــث لــم يتــم الكتابــة لشــركة‬\n‫الكهربــاء متشــيا مــع املــادة (‪ )1/254‬مــن نظــام املرافعــات الشــرعية ولــم‬\n‫جنــد أن فضيلتــه قــد خاطــب الســجالت للتأكــد مــن ســريان مفعــول‬\n‫الصــك وأنــه صالــح لالعتمــاد عليــه وعلــى فضيلتــه رصــد قررانــا هــذا‬\n‫بالضبــط واإلجابــة عليــه وملخصــه بالصــك وســجله ملالحظــة مــا ذكــر‬\n‫وإكمــال الــازم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ ،‬وعليــه فإنــي أجيــب أصحــاب الفضيلــة بــأن مــا ذكــر‬\n‫مــن مالحظــات محــل نظــر واعتبــار فيمــا لــو لــم تــرد دعــوى املدعــي أمــا‬\n‫وقــد ردت دعــوى املدعــي فــإن يف التقيــد بتلــك املالحظــات إطالــة ألمــد‬\n‫التقاضــي واملخــول بالعمــل مبــا ورد مــن مالحظــات هــي اجلهــة املنعقــد‬\n‫لهــا االختصــاص وعليــه فقــد أمــرت بإعــادة املعاملــة إلــى محكمــة‬\n‫االســتئناف إلكمــال الزمهــا واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/08/16‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫فقــد عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة عســير برقــم‬\n\n\n                                                                                    ‫‪44‬‬\n\f     ‫‪ 342332529‬يف ‪1434/11/10‬ه ـ برفقهــا القــرار الصــادر مــن‬\n     ‫الدائــرة احلقوقيــة الثانيــة برقــم ‪ 34341640‬يف ‪1434/10/27‬ه ـ ونــص‬\n     ‫احلاجــة منــه ‪ ( :‬وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة‬\n     ‫االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n     ‫وأحلقــه بالضبــط وصــك احلكــم بنــاء علــى قرارنــا رقــم ‪34223557‬‬\n     ‫يف ‪1434/5/27‬ه ـ قررنــا املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ ،‬وحتــى‬\n     ‫ال يخفــى جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n     ‫القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامة بنجــران برقم ‪341480661‬‬\n     ‫وتاريــخ ‪1434/9/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n     ‫‪... /‬برقــم ‪ 347226‬يف ‪1434/1/10‬ه ـ اخلــاص بدعــوى ‪ ... /‬و‪ ...‬و‪ ...‬و‪...‬‬\n     ‫أبنــاء ‪...‬ضــد ‪ /‬الشــركة الســعودية للكهربــاء بنجــران بشــأن ملكيــة‬\n     ‫عقــار املتضمــن حكــم فضيلتــه مبــا هــو مــدون بالصــك ومفصــل فيــه‪،‬‬\n     ‫وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط‬\n     ‫ـاء علــى قرارنــا رقــم ‪ 34223557‬يف ‪1434/5/27‬ه ـ‬           ‫وصــك احلكــم بنـ ً‬\n     ‫قررنــا املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل املوفــق ‪.‬‬\n                              ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪45‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":39,"source_page_end":45,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1634e97522ce413c5fba75723b62527594393ad9004eb7861efe36dd83db42c9","normalized_text_hash":"717f24fa4970ee298e89bdc2cfe8554f69c1297d77cdc092f7b5e9659c96e665","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p39-347226"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

